package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.service.RequestScopeService;
import EmployeeManagementSystem.entity.TaxDeclaration; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.TaxDeclarationService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/tax-declarations") public class TaxDeclarationController{
 private final TaxDeclarationService service; private final JwtUtil jwt; private final EmployeeRepository employees; private final RequestScopeService scope; public TaxDeclarationController(TaxDeclarationService s,JwtUtil j,EmployeeRepository e,RequestScopeService scope){this.scope=scope;service=s;jwt=j;employees=e;}
 private String tok(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(tok(a));} private String role(String a){String r=jwt.extractRole(tok(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR").contains(r);}
 @GetMapping("/my") public List<TaxDeclaration> my(@RequestHeader("Authorization")String a){return service.my(user(a));}
 @GetMapping public List<TaxDeclaration> all(@RequestHeader("Authorization")String a){if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");return scope.visibleTo(role(a),user(a),service.all());}
 @PostMapping public TaxDeclaration create(@RequestHeader("Authorization")String a,@RequestBody TaxDeclaration x){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(e->e.getFullName()).orElse(u);try{return service.create(x,u,n);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/{id}/submit") public TaxDeclaration submit(@PathVariable Long id,@RequestHeader("Authorization")String a){try{return service.submit(id,user(a));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/{id}/review") public TaxDeclaration review(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,Object>b){scope.assertCanReviewById(role(a),user(a),service.all(),id);if(!mgmt(role(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"HR/Admin access required.");try{return service.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")),user(a));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
}
